namespace FiveSmartFarmCreators.Ichu.Platform.OperationsMonitoring.Interfaces.Rest.Resources;

/// <summary>
///     Resource representing a stored livestock operation.
/// </summary>
/// <param name="OperationId">The identifier generated by the client.</param>
/// <param name="RanchId">The ranch that owns the animal.</param>
/// <param name="AnimalId">The animal the operation was applied to.</param>
/// <param name="Type">The kind of operation.</param>
/// <param name="IsClinical">Whether the operation is a clinical intervention.</param>
/// <param name="OccurredAt">The instant the operation happened.</param>
/// <param name="ReceivedAt">The instant the cloud received the operation.</param>
/// <param name="AuthorId">The account that registered the operation.</param>
/// <param name="Observation">The free-text observation.</param>
/// <param name="Product">The administered product.</param>
/// <param name="Dose">The administered dose.</param>
public record LivestockOperationResource(
    Guid OperationId,
    Guid RanchId,
    Guid AnimalId,
    string Type,
    bool IsClinical,
    DateTimeOffset OccurredAt,
    DateTimeOffset ReceivedAt,
    Guid AuthorId,
    string? Observation,
    string? Product,
    string? Dose);
